    /** A seeded line's billing increment: its invoice's client's increment for the line's unit type; null for none. */
    private BigDecimal lineIncrement(Long invoiceId, Map<String, Object> line) {
        if (line.get("unitType") == null) {
            return null;
        }
        List<BigDecimal> found = jdbc.queryForList("SELECT r.increment FROM client_rate r JOIN invoice i ON i.client_id = r.client_id "
                + "WHERE i.id = ? AND LOWER(r.unit_type) = LOWER(?)", BigDecimal.class, invoiceId,
                line.get("unitType").toString().trim());
        return found.isEmpty() ? null : found.get(0);
    }

    /** A rate card or price list entry as read back: its unit type and a single unitPrice or tiers. */
    private static Map<String, Object> rate(String unitType, BigDecimal unitPrice, RateTiers tiers) {
        Map<String, Object> rate = new LinkedHashMap<>();
        rate.put("unitType", unitType);
        if (tiers == null) {
            rate.put("unitPrice", unitPrice);
        } else {
            rate.put("tiers", tiers.bands().stream().map(b -> {
                Map<String, Object> band = new LinkedHashMap<>();
                if (b.units() != null) {
                    band.put("units", b.units());
                }
    }

    /**
     * Refuses an amount entered with more decimals than the currency has: whole yen for a yen client
     * (the cent is already checked for the rest).
     */
    /** A line's unit price, and the tiers it is priced in (null when it has a single price). */
    private record LinePrice(BigDecimal unitPrice, String tiers, BigDecimal increment) {
    }

    /**
     * A line's price: the unit price entered, or else the client's rate for the line's unit type —
     * a single price, or tiers starting from the first band — or, when the card has none, the
     * workspace price list's converted into the client's currency (see {@link PriceList}). Refused when neither is there, and a
     * single price with more decimals than the currency has. Either way the line is billed in the
     * increment the client's rate card has for its unit type, if any.
     */
    private LinePrice linePrice(Invoice invoice, String unitType, BigDecimal unitPrice) {
        Client client = unitType == null ? null : clients.findById(invoice.getClientId()).orElse(null);
        ClientRate rate = client == null ? null : client.rateFor(unitType);
        BigDecimal increment = rate == null ? null : rate.getIncrement();
        if (unitPrice != null) {
            requireWhole(invoice.currency(), unitPrice, "The unit price");
            return new LinePrice(unitPrice, null, increment);
        }
        if (unitType == null) {
            throw new InvoiceRejectedException("Enter a unit price or a unit type.");
        }
        if (rate == null) {
            LocalDate on = invoice.getIssueDate() == null ? today.date() : invoice.getIssueDate();
            PriceList.Converted listed = priceList.priceFor(unitType, invoice.currency(), on);
            if (listed == null) {
                throw new InvoiceRejectedException("The client's rate card has no rate for " + unitType
                        + "; enter a unit price.");
            }
            return new LinePrice(listed.unitPrice(), listed.tiers(), null);
        }
